INSERT INTO `page_contents` VALUES (1,'home','home.hero.title','Judul Hero (Baris 1)','Selamat Datang','text','2026-09-15 06:46:56','2026-09-15 06:46:56'),(2,'home','home.hero.middle','Judul Hero (Baris 2 - Penghubung)','di','text','2026-09-15 06:46:56','2026-09-15 06:46:56'),(3,'home','home.hero.accent','Judul Hero (Baris 3 - Aksen)','LPPM IBIKKG','text','2026-09-15 06:46:56','2026-09-15 06:46:56'),(4,'home','home.hero.desc','Deskripsi Hero Utama','Lembaga Penelitian dan Pengabdian kepada Masyarakat (LPPM) Institut Bisnis dan Informatika Kwik Kian Gie berkomitmen memajukan riset ilmiah, pengabdian masyarakat, serta publikasi berkualitas tinggi.','textarea','2026-09-15 06:46:56','2026-09-15 06:46:56'),(5,'home','home.stats.pilar_count','Angka Statistik 1','3','text','2026-09-15 06:46:56','2026-09-15 06:46:56'),(6,'home','home.stats.pilar_label','Label Statistik 1','Pilar Utama','text','2026-09-15 06:46:56','2026-09-15 06:46:56'),(7,'home','home.stats.publikasi_count','Angka Statistik 2','100+','text','2026-09-15 06:46:56','2026-09-15 06:46:56'),(8,'home','home.stats.publikasi_label','Label Statistik 2','Publikasi Aktif','text','2026-09-15 06:46:56','2026-09-15 06:46:56'),(9,'home','home.stats.standar_count','Angka Statistik 3','Unggul','text','2026-09-15 06:46:56','2026-09-15 06:46:56'),(10,'home','home.stats.standar_label','Label Statistik 3','Standar Mutu','text','2026-09-15 06:46:56','2026-09-15 06:46:56'),(11,'home','home.stats.dukungan_count','Angka Statistik 4','100%','text','2026-09-15 06:46:56','2026-09-15 06:46:56'),(12,'home','home.stats.dukungan_label','Label Statistik 4','Dukungan Dosen','text','2026-09-15 06:46:56','2026-09-15 06:46:56'),(13,'profil.tentang-kami','about.hero.title','Judul Tentang Kami','Tentang LPPM IBI KKG','text','2026-09-15 06:46:56','2026-09-15 06:46:56'),(14,'profil.tentang-kami','about.hero.desc','Deskripsi Singkat Tentang Kami','Lembaga Penelitian dan Pengabdian kepada Masyarakat (LPPM) merupakan unit strategis yang mengelola, mengembangkan, dan mendukung penuh pelaksanaan riset ilmiah, pengabdian masyarakat, publikasi ilmiah, serta penguatan jejaring kerja sama tridharma.','textarea','2026-09-15 06:46:56','2026-09-15 06:46:56'),(15,'profil.tentang-kami','about.short_profile.title','Judul Profil Singkat','Profil Singkat','text','2026-09-15 06:46:56','2026-09-15 06:46:56'),(16,'profil.tentang-kami','about.short_profile.text1','Paragraf Profil Singkat 1','LPPM IBI KKG bertugas mengelola proses administratif, akademik, dan strategis dalam pelaksanaan penelitian dosen, pengabdian kepada masyarakat, publikasi ilmiah, serta pengembangan kolaborasi dengan mitra internal maupun eksternal.','textarea','2026-09-15 06:46:56','2026-09-15 06:46:56'),(17,'profil.tentang-kami','about.short_profile.text2','Paragraf Profil Singkat 2','Melalui pengelolaan yang profesional, transparan, dan berbasis teknologi informasi, LPPM berkomitmen memfasilitasi sivitas akademika guna melahirkan karya riset inovatif dan program pengabdian yang memberikan kontribusi nyata bagi masyarakat luas.','textarea','2026-09-15 06:46:56','2026-09-15 06:46:56'),(18,'profil.tentang-kami','about.tasks.text','Tugas Utama (Satu baris per Tugas, tekan Enter)','Mengelola administrasi dan pendanaan internal/eksternal penelitian dosen.\nMengoordinasikan dan merancang agenda pengabdian kepada masyarakat (Abdimas).\nMendorong luaran ilmiah bermutu tinggi melalui pembinaan berkelanjutan.\nMenyediakan standarisasi panduan, dokumen administrasi, serta template resmi.\nMembangun kerja sama strategis multi-sektoral dengan industri, pemerintah, dan LSM.','textarea','2026-09-15 06:46:56','2026-09-15 06:46:56'),(19,'profil.tentang-kami','about.functions.text','Fungsi Strategis (Satu baris per Fungsi, tekan Enter)','Sebagai katalisator utama pengembangan iklim riset institusi.\nSebagai jembatan hilirisasi karya keilmuan dosen ke masyarakat.\nSebagai fasilitator peningkatan sitasi dan indeks publikasi ilmiah global.\nSebagai penyedia platform terintegrasi untuk seluruh layanan tridharma.','textarea','2026-09-15 06:46:56','2026-09-15 06:46:56'),(20,'profil.tentang-kami','about.pillar.penelitian','Ruang Lingkup: Deskripsi Penelitian','Mengelola pengajuan proposal hibah, proses monitoring evaluasi berkala, pelaporan keuangan, hingga pendampingan paten dan HKI hasil riset dosen.','textarea','2026-09-15 06:46:56','2026-09-15 06:46:56'),(21,'profil.tentang-kami','about.pillar.abdimas','Ruang Lingkup: Deskripsi Abdimas','Menyelenggarakan kegiatan pengabdian masyarakat berorientasi dampak, memandu program binaan desa mitra, serta mengoordinasikan laporan pengabdian.','textarea','2026-09-15 06:46:56','2026-09-15 06:46:56'),(22,'profil.tentang-kami','about.pillar.publikasi','Ruang Lingkup: Deskripsi Publikasi & Jurnal','Dukungan penyuntingan artikel ilmiah, penyediaan direktori jurnal bereputasi nasional dan internasional, serta pengurusan insentif publikasi.','textarea','2026-09-15 06:46:56','2026-09-15 06:46:56'),(23,'profil.tentang-kami','about.values.tertib','Core Value: Deskripsi Tertib','Tata kelola administrasi yang rapi, transparan, terdokumentasi, dan sesuai dengan standar nasional DIKTI.','textarea','2026-09-15 06:46:56','2026-09-15 06:46:56'),(24,'profil.tentang-kami','about.values.transparan','Core Value: Deskripsi Transparan','Keterbukaan informasi terkait skema dana hibah riset, penilaian proposal, hasil monev, hingga pembagian insentif.','textarea','2026-09-15 06:46:56','2026-09-15 06:46:56'),(25,'profil.tentang-kami','about.values.adaptif','Core Value: Deskripsi Adaptif','Terus berinovasi dan menyesuaikan layanan dengan kebutuhan digitalisasi tridharma perguruan tinggi.','textarea','2026-09-15 06:46:56','2026-09-15 06:46:56'),(26,'profil.tentang-kami','about.values.berkualitas','Core Value: Deskripsi Berkualitas','Memprioritaskan mutu hasil luaran yang berdaya saing nasional serta berorientasi dampak global.','textarea','2026-09-15 06:46:56','2026-09-15 06:46:56'),(27,'profil.tentang-kami','about.commitment.title','Judul Komitmen Kami','Pemberdayaan Berkelanjutan & Dampak Nyata','text','2026-09-15 06:46:56','2026-09-15 06:46:56'),(28,'profil.tentang-kami','about.commitment.text','Paragraf Komitmen Kami','LPPM IBI KKG berkomitmen untuk secara konsisten memberikan pelayanan prima yang adaptif dan berorientasi kualitas. Melalui sinergi riset akademis dan program pengabdian inovatif, kami bertekad mempercepat pertumbuhan keilmuan civitas akademika dan mewujudkan kolaborasi bernilai tambah tinggi bagi masyarakat dan mitra strategis.','textarea','2026-09-15 06:46:56','2026-09-15 06:46:56'),(29,'profil.visi-misi','visi_misi.hero.title','Judul Visi & Misi','Arah Strategis','text','2026-09-15 06:46:56','2026-09-15 06:46:56'),(30,'profil.visi-misi','visi_misi.hero.desc','Deskripsi Hero Visi & Misi','Tujuan dan Sasaran Strategis Lembaga Penelitian dan Pengabdian kepada Masyarakat (LPPM) IBI Kwik Kian Gie.','textarea','2026-09-15 06:46:56','2026-09-15 06:46:56'),(31,'profil.visi-misi','visi_misi.visi.text','Teks Visi LPPM','Menjadi lembaga pengelola tridharma yang unggul secara nasional, adaptif, dan berorientasi kualitas untuk menghasilkan riset inovatif dan pengabdian yang berdampak nyata bagi masyarakat luas pada tahun 2030.','textarea','2026-09-15 06:46:56','2026-09-15 06:46:56'),(32,'profil.visi-misi','visi_misi.misi.text','Teks Misi LPPM (Gunakan Enter untuk pemisah)','Meningkatkan kuantitas dan kualitas penelitian dosen yang relevan dengan kebutuhan industri.\nMenyelenggarakan pengabdian masyarakat berbasis produk inovasi dan tepat guna.\nMendorong luaran jurnal ilmiah terakreditasi nasional (SINTA) dan internasional bereputasi.','textarea','2026-09-15 06:46:56','2026-09-15 06:46:56'),(33,'profil.struktur-organisasi','struktur.hero.title','Judul Struktur Organisasi','Struktur Organisasi','text','2026-09-15 06:46:56','2026-09-15 06:46:56'),(34,'profil.struktur-organisasi','struktur.hero.desc','Deskripsi Hero Struktur','Susunan kepengurusan dan tata kelola organisasi Lembaga Penelitian dan Pengabdian kepada Masyarakat (LPPM) IBI Kwik Kian Gie.','textarea','2026-09-15 06:46:56','2026-09-15 06:46:56'),(35,'profil.struktur-organisasi','struktur.pimpinan.ketua','Nama Ketua LPPM','Dr. Carmel Meiden, S.E., M.Si., Ak, CA, CSRA.','text','2026-09-15 06:46:56','2026-09-15 06:46:56'),(36,'profil.struktur-organisasi','struktur.pimpinan.sekretaris','Nama Sekretaris LPPM','Amelia Sandra, S.E., Ak., M.Si., M.Ak.','text','2026-09-15 06:46:56','2026-09-15 06:46:56'),(37,'profil.prestasi','prestasi.hero.title','Judul Halaman Prestasi','Prestasi & Penghargaan','text','2026-09-15 06:46:56','2026-09-15 06:46:56'),(38,'profil.prestasi','prestasi.hero.desc','Deskripsi Halaman Prestasi','Catatan keunggulan akademik, hibah penelitian nasional, dan luaran bermutu tinggi dari sivitas akademika IBI Kwik Kian Gie.','textarea','2026-09-15 06:46:56','2026-09-15 06:46:56'),(39,'akademisi','dosen.hero.title','Judul Menu Akademisi','Akademisi & Dosen Peneliti','text','2026-09-15 06:46:56','2026-09-15 06:46:56'),(40,'akademisi','dosen.hero.desc','Deskripsi Menu Akademisi','Direktori dosen pengajar, kepangkatan akademik, serta fokus kepakaran tridharma penelitian di IBI Kwik Kian Gie.','textarea','2026-09-15 06:46:56','2026-09-15 06:46:56'),(41,'penelitian','penelitian.hero.title','Judul Halaman Penelitian','Penelitian & Pengabdian LPPM','text','2026-09-15 06:46:56','2026-09-15 06:46:56'),(42,'penelitian','penelitian.hero.desc','Deskripsi Halaman Penelitian','Informasi skema pendanaan riset internal/nasional, pengumuman seleksi, dan panduan pengabdian masyarakat.','textarea','2026-09-15 06:46:56','2026-09-15 06:46:56'),(43,'publikasi','publikasi.hero.title','Judul Halaman Publikasi','Publikasi & Jurnal Ilmiah','text','2026-09-15 06:46:56','2026-09-15 06:46:56'),(44,'publikasi','publikasi.hero.desc','Deskripsi Halaman Publikasi','Akses jurnal resmi terakreditasi, artikel ilmiah, prosiding nasional, serta direktori indeksasi sitasi dosen.','textarea','2026-09-15 06:46:56','2